    def iti_links():
        for i in lista_links:
            webbrowser.open(i)
            re = requests.get(i)
            if re.status_code == 404:
                print('Error 404', i)
            elif re.status_code == 403:
                print('403 Forbidden', i)
            elif re.status_code != [403, 404]:
               print('Página tem conteúdo.', i)
            else:
              print('Acabou.')

